{"name":"20261115000000_snapshot_recording","checksum":"4a01d961023af50092e641814f724af4480bd97223cb0f2a4c8b44d67fba6799","sql":"CREATE TYPE \"SnapshotFeedbackSource\" AS ENUM ('GENERAL_GUIDANCE', 'AI');\nALTER TABLE \"daily_snapshots\" ADD COLUMN \"idempotency_key\" TEXT,\n ADD COLUMN \"etag\" TEXT,\n ADD COLUMN \"feedback_source\" \"SnapshotFeedbackSource\" NOT NULL DEFAULT 'GENERAL_GUIDANCE';\nCREATE UNIQUE INDEX \"daily_snapshots_user_id_idempotency_key_key\" ON \"daily_snapshots\"(\"user_id\", \"idempotency_key\");\nCREATE TABLE \"snapshot_upload_sessions\" (\n \"id\" TEXT NOT NULL PRIMARY KEY,\n \"user_id\" TEXT NOT NULL,\n \"s3_key\" TEXT NOT NULL,\n \"mime_type\" TEXT NOT NULL,\n \"file_size_bytes\" INTEGER NOT NULL CHECK (\"file_size_bytes\" BETWEEN 10240 AND 10485760),\n \"record_date\" DATE NOT NULL,\n \"status\" \"UploadStatus\" NOT NULL DEFAULT 'PENDING',\n \"etag\" TEXT,\n \"expires_at\" TIMESTAMPTZ NOT NULL,\n \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n CONSTRAINT \"snapshot_upload_sessions_user_id_fkey\" FOREIGN KEY(\"user_id\") REFERENCES \"users\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE\n);\nCREATE UNIQUE INDEX \"snapshot_upload_sessions_s3_key_key\" ON \"snapshot_upload_sessions\"(\"s3_key\");\nCREATE INDEX \"snapshot_upload_sessions_user_id_created_at_idx\" ON \"snapshot_upload_sessions\"(\"user_id\", \"created_at\");\nCREATE INDEX \"snapshot_upload_sessions_status_expires_at_idx\" ON \"snapshot_upload_sessions\"(\"status\", \"expires_at\");\n"},
{"name":"20261115010000_product_curation","checksum":"1bf8ef3d5bee41fb358396e561b23b0694492428e1b4f52440c617299e99ee81","sql":"CREATE TYPE \"ProductStatus\" AS ENUM ('ACTIVE', 'OUT_OF_STOCK', 'DISCONTINUED', 'UNAVAILABLE');\nCREATE TYPE \"RecommendationTier\" AS ENUM ('PRIMARY', 'SECONDARY');\nALTER TABLE \"products\"\n  ADD COLUMN \"key_ingredients\" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],\n  ADD COLUMN \"full_ingredients\" TEXT NOT NULL DEFAULT '',\n  ADD COLUMN \"thumbnail_url\" TEXT,\n  ADD COLUMN \"status\" \"ProductStatus\" NOT NULL DEFAULT 'ACTIVE',\n  ADD COLUMN \"health_check_fail_count\" INTEGER NOT NULL DEFAULT 0 CHECK (\"health_check_fail_count\" >= 0),\n  ADD COLUMN \"last_checked_at\" TIMESTAMPTZ;\nUPDATE \"products\" SET \"key_ingredients\" = \"ingredients\", \"full_ingredients\" = array_to_string(\"ingredients\", ', ');\nALTER TABLE \"product_recommendations\"\n  ADD COLUMN \"tier\" \"RecommendationTier\" NOT NULL DEFAULT 'PRIMARY',\n  ADD COLUMN \"target_ingredients\" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];\n-- Preserve legacy rows. Refuse ambiguous >2 mappings instead of deleting data.\nDO $$ BEGIN\n  IF EXISTS (SELECT 1 FROM \"product_recommendations\" GROUP BY \"report_id\", \"category\" HAVING count(*) > 2) THEN\n    RAISE EXCEPTION 'Review legacy recommendation groups with more than two products before migrating';\n  END IF;\nEND $$;\nWITH ranked AS (\n SELECT r.id, row_number() OVER (PARTITION BY r.report_id, r.category ORDER BY p.is_primary DESC, r.created_at, r.id) AS n\n FROM product_recommendations r JOIN products p ON p.id = r.product_id\n)\nUPDATE product_recommendations r SET tier = CASE WHEN ranked.n = 1 THEN 'PRIMARY'::\"RecommendationTier\" ELSE 'SECONDARY'::\"RecommendationTier\" END FROM ranked WHERE r.id = ranked.id;\nCREATE UNIQUE INDEX \"product_recommendations_report_id_category_tier_key\" ON \"product_recommendations\"(\"report_id\", \"category\", \"tier\");\nCREATE TABLE \"affiliate_click_logs\" (\n \"id\" TEXT PRIMARY KEY,\n \"product_id\" TEXT NOT NULL REFERENCES \"products\"(\"id\") ON DELETE RESTRICT ON UPDATE CASCADE,\n \"report_id\" TEXT,\n \"user_id\" TEXT,\n \"guest_device_id\" TEXT,\n \"tier\" \"RecommendationTier\" NOT NULL DEFAULT 'PRIMARY',\n \"source_baumann_type\" VARCHAR(4),\n \"target_url\" TEXT NOT NULL,\n \"user_agent\" VARCHAR(512),\n \"clicked_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX \"affiliate_click_logs_product_id_clicked_at_idx\" ON \"affiliate_click_logs\"(\"product_id\", \"clicked_at\");\nCREATE INDEX \"affiliate_click_logs_user_id_idx\" ON \"affiliate_click_logs\"(\"user_id\");\nCREATE INDEX \"affiliate_click_logs_guest_device_id_idx\" ON \"affiliate_click_logs\"(\"guest_device_id\");\n"},
{"name":"20261118000000_ai_inference_audit","checksum":"4b2c537e0bf8df82e3dda18606bcd5526993b42b0a5e42f225bb1fc900380ee1","sql":"CREATE TYPE \"AiInferenceStatus\" AS ENUM ('SUCCESS', 'TIMEOUT', 'ERROR');\nCREATE TABLE \"ai_inference_audit_logs\" (\n  \"id\" TEXT NOT NULL PRIMARY KEY,\n  \"session_id\" TEXT,\n  \"provider\" TEXT NOT NULL CHECK (\"provider\" IN ('OPENAI', 'GEMINI')),\n  \"model_name\" TEXT NOT NULL,\n  \"prompt_template_hash\" TEXT NOT NULL CHECK (\"prompt_template_hash\" ~ '^[a-f0-9]{64}$'),\n  \"latency_ms\" INTEGER NOT NULL CHECK (\"latency_ms\" >= 0),\n  \"prompt_tokens\" INTEGER CHECK (\"prompt_tokens\" >= 0),\n  \"completion_tokens\" INTEGER CHECK (\"completion_tokens\" >= 0),\n  \"total_tokens\" INTEGER CHECK (\"total_tokens\" >= 0),\n  \"status\" \"AiInferenceStatus\" NOT NULL,\n  \"error_message\" TEXT,\n  \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT \"ai_audit_error_code\" CHECK (\"error_message\" IS NULL OR \"error_message\" IN (\n    'AI_GATEWAY_TIMEOUT', 'AI_PROVIDER_ERROR', 'AI_INVALID_RESPONSE', 'AI_UNSAFE_RESPONSE',\n    'AI_INVALID_IMAGE', 'AI_INVALID_REQUEST', 'AI_DISABLED', 'AI_CONFIGURATION_UNAVAILABLE'\n  ))\n);\nCREATE INDEX \"ai_inference_audit_logs_session_id_idx\" ON \"ai_inference_audit_logs\"(\"session_id\");\nCREATE INDEX \"ai_inference_audit_logs_status_created_at_idx\" ON \"ai_inference_audit_logs\"(\"status\", \"created_at\");\n"},
{"name":"20261118000000_biometric_consent_versions","checksum":"9dc32b66e3eb149f4d0e3a15cf14f9aeb4a871116545e96dab629ef6601c9c81","sql":"CREATE TYPE \"ConsentType\" AS ENUM ('BIOMETRIC_FACE_DATA');\nCREATE TABLE consent_terms_versions (\n  id TEXT PRIMARY KEY,\n  consent_type \"ConsentType\" NOT NULL,\n  version TEXT NOT NULL,\n  title TEXT NOT NULL,\n  content_markdown TEXT NOT NULL,\n  is_active BOOLEAN NOT NULL DEFAULT FALSE,\n  enacted_at TIMESTAMPTZ NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT consent_terms_nonempty CHECK (length(version) BETWEEN 1 AND 40 AND length(title) > 0 AND length(content_markdown) > 0)\n);\nCREATE UNIQUE INDEX uq_terms_type_version ON consent_terms_versions(consent_type, version);\nCREATE UNIQUE INDEX consent_one_active_version ON consent_terms_versions(consent_type) WHERE is_active;\nCREATE INDEX consent_terms_versions_consent_type_is_active_idx ON consent_terms_versions(consent_type, is_active);\n\nDROP INDEX user_consent_histories_user_id_key;\nALTER TABLE user_consent_histories ALTER COLUMN user_id DROP NOT NULL;\nALTER TABLE user_consent_histories\n  ADD COLUMN guest_device_id TEXT,\n  ADD COLUMN terms_version_id TEXT REFERENCES consent_terms_versions(id) ON DELETE RESTRICT ON UPDATE CASCADE,\n  ADD COLUMN consent_type \"ConsentType\" NOT NULL DEFAULT 'BIOMETRIC_FACE_DATA',\n  ADD COLUMN user_agent TEXT,\n  ADD COLUMN ip_source TEXT NOT NULL DEFAULT 'UNAVAILABLE',\n  ADD CONSTRAINT consent_owner_required CHECK (user_id IS NOT NULL OR guest_device_id IS NOT NULL),\n  ADD CONSTRAINT consent_ip_source CHECK (ip_source IN ('UNAVAILABLE','TRUSTED_HEADER'));\nCREATE INDEX user_consent_histories_user_id_consent_type_idx ON user_consent_histories(user_id,consent_type);\nCREATE INDEX user_consent_histories_guest_device_id_consent_type_idx ON user_consent_histories(guest_device_id,consent_type);\nCREATE INDEX user_consent_histories_terms_version_id_idx ON user_consent_histories(terms_version_id);\n\nCREATE FUNCTION protect_consent_audit() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  -- Only the explicit one-time ownership binding is mutable; original actor,\n  -- version, decision, timestamp, IP and UA remain the original audit facts.\n  IF OLD.user_id IS NULL AND NEW.user_id IS NOT NULL AND OLD.guest_device_id IS NOT NULL\n     AND (to_jsonb(NEW) - 'user_id') = (to_jsonb(OLD) - 'user_id') THEN\n    RETURN NEW;\n  END IF;\n  RAISE EXCEPTION 'Consent audit facts are immutable' USING ERRCODE='23514';\nEND; $$;\nCREATE TRIGGER consent_audit_immutable BEFORE UPDATE ON user_consent_histories\nFOR EACH ROW EXECUTE FUNCTION protect_consent_audit();\n\nCREATE FUNCTION protect_consent_terms() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF (to_jsonb(NEW) - 'is_active') IS DISTINCT FROM (to_jsonb(OLD) - 'is_active') THEN\n    RAISE EXCEPTION 'Publish a new terms version instead of rewriting terms' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND; $$;\nCREATE TRIGGER consent_terms_immutable BEFORE UPDATE ON consent_terms_versions\nFOR EACH ROW EXECUTE FUNCTION protect_consent_terms();\n\n-- Draft only: no operational retention/deletion claims or automatic publication.\nINSERT INTO consent_terms_versions(id,consent_type,version,title,content_markdown,is_active,enacted_at)\nVALUES ('61a9319c-0b2f-4fd5-868a-770c37960801','BIOMETRIC_FACE_DATA','v1.0-draft',\n'안면 사진 수집·이용 동의 문안 검토용 초안',\n'이 문안은 비활성 개발 초안이며 사용자 동의를 받을 수 없습니다. 수집 항목: 얼굴 사진과 외관 참고 정보. 목적: 문진을 보조하는 일상 스킨케어 참고 리포트. 거부 시 사진 기능은 이용할 수 없으며 문진만 이용할 수 있습니다. 실제 보관 기간, 삭제·철회 처리, 외부 AI 제공자 및 처리 범위를 운영자가 검증하고 확정한 새 버전을 게시하기 전까지 사진 업로드를 허용하지 않습니다. 현재 24시간 자동 삭제나 탈퇴 즉시 파기를 보장하지 않습니다.',\nFALSE, '2026-11-18T00:00:00Z');\n"},
{"name":"20261118010000_procedure_guides","checksum":"9fcfbddbab07a2ca522bf6c26884d76c03157a190633aab4a0d05e8553def06f","sql":"-- Extend the existing catalog without replacing report mappings or legacy rows.\nCREATE TYPE \"SkinConcernType\" AS ENUM ('ACNE_SCAR', 'PIGMENTATION', 'PORE_SEBUM', 'ELASTICITY', 'BARRIER_REDNESS');\nALTER TABLE \"medical_procedures\"\n  ALTER COLUMN \"min_price_krw\" DROP NOT NULL,\n  ALTER COLUMN \"max_price_krw\" DROP NOT NULL,\n  ADD COLUMN \"code\" TEXT,\n  ADD COLUMN \"aliases\" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],\n  ADD COLUMN \"concern_type\" \"SkinConcernType\",\n  ADD COLUMN \"recovery_period\" TEXT,\n  ADD COLUMN \"checklist_questions\" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],\n  ADD COLUMN \"sort_order\" INTEGER NOT NULL DEFAULT 0,\n  ADD COLUMN \"price_basis\" TEXT,\n  ADD COLUMN \"price_observations\" JSONB NOT NULL DEFAULT '[]';\nCREATE UNIQUE INDEX \"medical_procedures_code_key\" ON \"medical_procedures\"(\"code\");\nCREATE INDEX \"medical_procedures_concern_type_is_active_idx\" ON \"medical_procedures\"(\"concern_type\", \"is_active\");\nCREATE INDEX \"medical_procedures_sort_order_idx\" ON \"medical_procedures\"(\"sort_order\");\n-- No event prices or purported market averages are inserted by a migration.\n"},
{"name":"20261119000000_account_deletion_audit","checksum":"aa909d1e43a6f1f5bad2994c7d346ce895edfaec0a4cdff75c8ce5f17d9e9bdb","sql":"CREATE TABLE \"deletion_audit_logs\" (\n    \"id\" TEXT NOT NULL,\n    \"user_hash\" TEXT NOT NULL,\n    \"deleted_images_count\" INTEGER NOT NULL CHECK (\"deleted_images_count\" >= 0),\n    \"deleted_records_count\" INTEGER NOT NULL CHECK (\"deleted_records_count\" >= 0),\n    \"completed_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    CONSTRAINT \"deletion_audit_logs_pkey\" PRIMARY KEY (\"id\")\n);\nCREATE INDEX \"deletion_audit_logs_user_hash_idx\" ON \"deletion_audit_logs\"(\"user_hash\");\n"},
{"name":"20261119010000_ingredient_caution_rules","checksum":"02acdbde9a790e2603a6f9cfe13c96a003b1afa318043dbe333d558824591e67","sql":"CREATE TYPE \"CautionLevel\" AS ENUM ('INFO', 'CAUTION', 'WARNING');\nCREATE TYPE \"BaumannAxisTarget\" AS ENUM ('ALL', 'OILY', 'DRY', 'SENSITIVE', 'RESISTANT', 'PIGMENTED', 'NON_PIGMENTED', 'WRINKLED', 'TIGHT');\nCREATE TABLE \"ingredient_caution_rules\" (\n  \"id\" TEXT NOT NULL PRIMARY KEY,\n  \"standard_name\" TEXT NOT NULL,\n  \"inci_name\" TEXT,\n  \"aliases\" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],\n  \"target_axis\" \"BaumannAxisTarget\" NOT NULL,\n  \"caution_level\" \"CautionLevel\" NOT NULL DEFAULT 'CAUTION',\n  \"reason_ko\" TEXT NOT NULL,\n  \"description_ko\" TEXT NOT NULL,\n  \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  \"updated_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE UNIQUE INDEX \"ingredient_caution_rules_standard_name_key\" ON \"ingredient_caution_rules\"(\"standard_name\");\nCREATE INDEX \"ingredient_caution_rules_target_axis_idx\" ON \"ingredient_caution_rules\"(\"target_axis\");\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000001','변성알코올','Alcohol Denat.',ARRAY['에탄올','Ethanol','Alcohol','알코올'],'SENSITIVE','CAUTION','휘발성 알코올이 포함되어 있습니다. 민감하게 느껴지는 피부에서는 건조감이나 따가움이 생길 수 있어 사용 반응을 확인해 주세요.','용매로 사용되며 가벼운 사용감을 만드는 데 쓰입니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000002','향료','Fragrance',ARRAY['Parfum','Perfume','합성향료'],'SENSITIVE','CAUTION','향료가 포함되어 있습니다. 향 성분에 민감하거나 알레르기 경험이 있다면 상세 표기와 사용 반응을 확인해 주세요.','제품에 향을 부여하는 데 사용됩니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000003','소듐라우릴설페이트','Sodium Lauryl Sulfate',ARRAY['SLS'],'DRY','CAUTION','세정 성분이 포함되어 있습니다. 건조하게 느껴지는 피부에서는 세정 후 당김이 생길 수 있습니다. 제품 용도와 사용 시간을 확인해 주세요.','기름 성분과 물이 섞이도록 돕고 세정에 사용됩니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000004','소듐라우레스설페이트','Sodium Laureth Sulfate',ARRAY['SLES'],'DRY','CAUTION','세정 성분이 포함되어 있습니다. 건조한 피부에서는 세정 후 느낌과 사용 빈도를 확인해 주세요.','세정과 거품 형성에 사용되는 계면활성제입니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000005','살리실릭애씨드','Salicylic Acid',ARRAY['살리실산'],'SENSITIVE','CAUTION','각질 정돈 성분이 포함되어 있습니다. 전성분만으로 함량·pH를 알 수 없으므로 민감한 피부에서는 사용 빈도와 다른 각질 관리 제품의 병용을 확인해 주세요.','피부 표면의 각질을 정돈하는 용도로 사용됩니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000006','글라이콜릭애씨드','Glycolic Acid',ARRAY['글리콜릭애씨드','글리콜산'],'SENSITIVE','CAUTION','각질 정돈 성분이 포함되어 있습니다. 전성분만으로 농도를 판단할 수 없습니다. 민감한 피부에서는 사용 반응과 제품 사용법을 확인해 주세요.','피부 표면의 각질을 정돈하는 용도로 사용됩니다.');\nINSERT INTO \"ingredient_caution_rules\" (\"id\",\"standard_name\",\"inci_name\",\"aliases\",\"target_axis\",\"caution_level\",\"reason_ko\",\"description_ko\") VALUES ('30000000-0000-4000-8000-000000000007','페퍼민트오일','Mentha Piperita Oil',ARRAY['Peppermint Oil'],'SENSITIVE','CAUTION','향을 부여하는 오일이 포함되어 있습니다. 향 성분에 민감한 피부에서는 사용 반응을 확인해 주세요.','제품의 향과 사용감을 위해 사용됩니다.');\n"},
{"name":"20261119020000_procedure_safety_guides","checksum":"658b147aa5deeb4b5680c3e62578da8e2014b358cf0881f5354977bb68cc5f1c","sql":"CREATE TABLE \"procedure_safety_guides\" (\n  \"id\" TEXT NOT NULL PRIMARY KEY,\n  \"procedure_id\" TEXT NOT NULL,\n  \"slug\" TEXT NOT NULL,\n  \"common_side_effects\" TEXT[] NOT NULL,\n  \"rare_risks\" TEXT[] NOT NULL,\n  \"contraindications\" TEXT[] NOT NULL,\n  \"post_care_instructions\" TEXT[] NOT NULL,\n  \"defense_questions\" JSONB NOT NULL,\n  \"disclaimer_text\" TEXT NOT NULL,\n  \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  \"updated_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT \"procedure_safety_guides_procedure_id_fkey\" FOREIGN KEY (\"procedure_id\") REFERENCES \"medical_procedures\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE\n);\nCREATE UNIQUE INDEX \"procedure_safety_guides_procedure_id_key\" ON \"procedure_safety_guides\"(\"procedure_id\");\nCREATE UNIQUE INDEX \"procedure_safety_guides_slug_key\" ON \"procedure_safety_guides\"(\"slug\");\nCREATE TABLE \"procedure_safety_rate_limits\" (\n  \"key_hash\" TEXT NOT NULL PRIMARY KEY,\n  \"request_count\" INTEGER NOT NULL CHECK (\"request_count\" BETWEEN 1 AND 121),\n  \"expires_at\" TIMESTAMPTZ NOT NULL\n);\nCREATE INDEX \"procedure_safety_rate_limits_expires_at_idx\" ON \"procedure_safety_rate_limits\"(\"expires_at\");\n"},
{"name":"20261119030000_rf_microneedling_risk_note","checksum":"39dc41b7d6f416f1ce28d2d1c44775735c91cb97a826ca385c710179dd1eb6a7","sql":"-- FDA safety communication (2025-10-15), limited to certain RF microneedling uses.\n-- Append only: preserve curated text, prices, questions and all other procedures.\n-- Both updates are one atomic statement. Repeat application adds no duplicate.\nWITH note AS (\n  SELECT 'RF 미세침 방식의 일부 사용에서는 흉터·지방 손실·신경 손상 등 중대한 합병증이 보고되었습니다. 비침습 RF와 구분해 사용할 장비·방식의 위험을 의료진에게 확인하세요.'::text AS content\n), updated_procedure AS (\n  UPDATE \"medical_procedures\" AS procedure\n  SET \"side_effects\" = array_append(COALESCE(procedure.\"side_effects\", ARRAY[]::text[]), note.content),\n      \"updated_at\" = CURRENT_TIMESTAMP\n  FROM note\n  WHERE procedure.\"code\" = 'P-RF'\n    AND NOT (note.content = ANY(COALESCE(procedure.\"side_effects\", ARRAY[]::text[])))\n  RETURNING procedure.\"id\"\n)\nUPDATE \"procedure_safety_guides\" AS guide\nSET \"rare_risks\" = array_append(COALESCE(guide.\"rare_risks\", ARRAY[]::text[]), note.content),\n    \"updated_at\" = CURRENT_TIMESTAMP\nFROM \"medical_procedures\" AS procedure, note\nWHERE guide.\"procedure_id\" = procedure.\"id\"\n  AND procedure.\"code\" = 'P-RF'\n  AND guide.\"slug\" = 'rf-tightening'\n  AND NOT (note.content = ANY(COALESCE(guide.\"rare_risks\", ARRAY[]::text[])));\n"},
{"name":"20261124000000_diagnostic_fallback","checksum":"44421554db61cb48a8fc1ccc170f9a9e987643bc14d60218bb5f2c7456e44816","sql":"ALTER TABLE \"diagnostic_reports\"\n  ADD COLUMN \"is_fallback\" BOOLEAN NOT NULL DEFAULT false,\n  ADD COLUMN \"fallback_reason\" TEXT;\n"},
{"name":"20261124000000_snapshot_milestones","checksum":"ae3fcfbdfd63695bc73f45761fd9f44f2b0061a325393275e16561524419036a","sql":"-- CreateEnum\nCREATE TYPE \"MilestoneType\" AS ENUM ('STREAK_3_DAYS', 'STREAK_7_DAYS');\n\n-- CreateTable\nCREATE TABLE \"snapshot_milestone_reports\" (\n    \"id\" TEXT NOT NULL,\n    \"user_id\" TEXT NOT NULL,\n    \"milestone_type\" \"MilestoneType\" NOT NULL,\n    \"achieved_streak_days\" INTEGER NOT NULL,\n    \"start_date\" DATE NOT NULL,\n    \"achieved_date\" DATE NOT NULL,\n    \"start_snapshot_id\" TEXT NOT NULL,\n    \"achieved_snapshot_id\" TEXT NOT NULL,\n    \"summary_comment\" TEXT NOT NULL,\n    \"initial_hydration\" \"SkinConditionLevel\",\n    \"current_hydration\" \"SkinConditionLevel\",\n    \"initial_soothing\" \"SkinConditionLevel\",\n    \"current_soothing\" \"SkinConditionLevel\",\n    \"initial_sebum\" \"SkinConditionLevel\",\n    \"current_sebum\" \"SkinConditionLevel\",\n    \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n\n    CONSTRAINT \"snapshot_milestone_reports_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateIndex\nCREATE INDEX \"snapshot_milestone_reports_user_id_achieved_date_id_idx\" ON \"snapshot_milestone_reports\"(\"user_id\", \"achieved_date\", \"id\");\n\n-- CreateIndex\nCREATE INDEX \"snapshot_milestone_reports_start_snapshot_id_idx\" ON \"snapshot_milestone_reports\"(\"start_snapshot_id\");\n\n-- CreateIndex\nCREATE INDEX \"snapshot_milestone_reports_achieved_snapshot_id_idx\" ON \"snapshot_milestone_reports\"(\"achieved_snapshot_id\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"snapshot_milestone_reports_user_id_milestone_type_achieved__key\" ON \"snapshot_milestone_reports\"(\"user_id\", \"milestone_type\", \"achieved_date\");\n\n-- AddForeignKey\nALTER TABLE \"snapshot_milestone_reports\" ADD CONSTRAINT \"snapshot_milestone_reports_user_id_fkey\" FOREIGN KEY (\"user_id\") REFERENCES \"users\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"snapshot_milestone_reports\" ADD CONSTRAINT \"snapshot_milestone_reports_start_snapshot_id_fkey\" FOREIGN KEY (\"start_snapshot_id\") REFERENCES \"daily_snapshots\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"snapshot_milestone_reports\" ADD CONSTRAINT \"snapshot_milestone_reports_achieved_snapshot_id_fkey\" FOREIGN KEY (\"achieved_snapshot_id\") REFERENCES \"daily_snapshots\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n"},
{"name":"20261124010000_affiliate_link_health","checksum":"bc2a8a969c56c5bbcfa9ecf58e605766a387ec80ed1589a12abab5a7b9ce5d35","sql":"CREATE TYPE \"LinkHealthStatus\" AS ENUM ('HEALTHY', 'UNHEALTHY', 'TIMEOUT', 'REDIRECT_LOOP');\nCREATE TYPE \"LinkActionTaken\" AS ENUM ('NONE', 'SWITCHED_TO_FALLBACK', 'FALLBACK_FAILED', 'MANUAL_ATTENTION_REQUIRED');\n\nCREATE TABLE \"affiliate_link_health_logs\" (\n  \"id\" TEXT NOT NULL PRIMARY KEY,\n  \"product_id\" TEXT NOT NULL,\n  \"checked_url\" TEXT NOT NULL,\n  \"http_status_code\" INTEGER,\n  \"response_time_ms\" INTEGER NOT NULL,\n  \"status\" \"LinkHealthStatus\" NOT NULL,\n  \"error_message\" TEXT,\n  \"action_taken\" \"LinkActionTaken\" NOT NULL DEFAULT 'NONE',\n  \"fallback_product_id\" TEXT,\n  \"checked_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX \"affiliate_link_health_logs_product_id_checked_at_idx\"\n  ON \"affiliate_link_health_logs\" (\"product_id\", \"checked_at\");\nCREATE INDEX \"affiliate_link_health_logs_status_checked_at_idx\"\n  ON \"affiliate_link_health_logs\" (\"status\", \"checked_at\");\n\n-- One fixed-window quota shared by every deployment instance.\nCREATE TABLE \"affiliate_link_health_quota\" (\n  \"id\" INTEGER PRIMARY KEY CHECK (\"id\" = 1),\n  \"minute\" INTEGER NOT NULL,\n  \"request_count\" INTEGER NOT NULL CHECK (\"request_count\" BETWEEN 1 AND 3)\n);\n"}
]$migration_payload$::jsonb;
  spec record;
  completed_count integer;
  started timestamptz;
BEGIN
  IF jsonb_array_length(plan)<>16 OR EXISTS (SELECT 1 FROM jsonb_to_recordset(plan) AS e(name text,checksum text,sql text) WHERE e.sql IS NULL OR e.checksum IS NULL OR encode(sha256(convert_to(e.sql,'UTF8')),'hex')<>e.checksum) THEN
    RAISE EXCEPTION 'Migration text is incomplete or modified; copy the complete original file';
  END IF;
  PERFORM pg_catalog.set_config('search_path','public, pg_catalog',true);
  PERFORM pg_catalog.set_config('lock_timeout','5s',true);
  IF NOT pg_catalog.pg_try_advisory_xact_lock(72707369::bigint) THEN
    RAISE EXCEPTION 'Another migration is running; stop and review';
  END IF;
  IF EXISTS (SELECT 1 FROM public."_prisma_migrations" WHERE rolled_back_at IS NULL AND finished_at IS NULL) THEN
    RAISE EXCEPTION 'Unresolved migration exists; stop and review';
  END IF;
  SELECT count(*) INTO completed_count FROM public."_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL;
  IF completed_count NOT IN (4,16) THEN
    RAISE EXCEPTION 'Unexpected completed migration count: %',completed_count;
  END IF;
  IF EXISTS (SELECT 1 FROM public."_prisma_migrations" m LEFT JOIN jsonb_to_recordset(plan) AS e(name text,checksum text,sql text)
    ON m.migration_name=e.name AND m.checksum=e.checksum WHERE m.finished_at IS NOT NULL AND m.rolled_back_at IS NULL AND e.name IS NULL) THEN
    RAISE EXCEPTION 'Unknown or modified migration history; stop and review';
  END IF;
  FOR spec IN SELECT value->>'name' AS name,value->>'checksum' AS checksum FROM jsonb_array_elements(plan) WITH ORDINALITY WHERE ordinality<=4 LOOP
    IF (SELECT count(*) FROM public."_prisma_migrations" WHERE migration_name=spec.name AND checksum=spec.checksum AND finished_at IS NOT NULL AND rolled_back_at IS NULL)<>1 THEN
      RAISE EXCEPTION 'Missing or duplicated baseline migration: %',spec.name;
    END IF;
  END LOOP;
  IF completed_count=4 THEN
    IF EXISTS (SELECT 1 FROM public.products WHERE ingredients IS NULL) THEN
      RAISE EXCEPTION 'Legacy product ingredients contain NULL; review before migrating';
    END IF;
    IF EXISTS (SELECT 1 FROM public.product_recommendations GROUP BY report_id,category HAVING count(*)>2) THEN
      RAISE EXCEPTION 'Legacy recommendation group has more than two products; review before migrating';
    END IF;
    FOR spec IN SELECT value->>'name' AS name,value->>'checksum' AS checksum,value->>'sql' AS sql FROM jsonb_array_elements(plan) WITH ORDINALITY WHERE ordinality>4 ORDER BY ordinality LOOP
      started:=clock_timestamp();
      EXECUTE spec.sql;
      INSERT INTO public."_prisma_migrations"(id,checksum,finished_at,migration_name,logs,rolled_back_at,started_at,applied_steps_count)
      VALUES(pg_catalog.gen_random_uuid()::text,spec.checksum,clock_timestamp(),spec.name,NULL,NULL,started,1);
    END LOOP;
  END IF;
  FOR spec IN SELECT * FROM jsonb_to_recordset(plan) AS e(name text,checksum text,sql text) LOOP
    IF (SELECT count(*) FROM public."_prisma_migrations" WHERE migration_name=spec.name AND checksum=spec.checksum AND finished_at IS NOT NULL AND rolled_back_at IS NULL)<>1 THEN
      RAISE EXCEPTION 'Incomplete or duplicated migration: %',spec.name;
    END IF;
  END LOOP;
  IF to_regclass('public.procedure_safety_guides') IS NULL OR to_regclass('public.procedure_safety_rate_limits') IS NULL
    OR to_regclass('public.snapshot_milestone_reports') IS NULL OR to_regclass('public.snapshot_upload_sessions') IS NULL
    OR to_regclass('public.affiliate_link_health_logs') IS NULL OR to_regclass('public.affiliate_link_health_quota') IS NULL
    OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='diagnostic_reports' AND column_name='is_fallback') THEN
    RAISE EXCEPTION 'Required migrated structure missing; stop and review';
  END IF;
  RAISE NOTICE 'Complete: 16 matching migrations. Application settings unchanged.';
END $apply_migrations$;
SELECT migration_name,finished_at,rolled_back_at FROM public."_prisma_migrations" ORDER BY started_at,migration_name;
